  <script>
    const categories = ["All Posts", "Engineering", "Community", "Company News", "Customers", "v0", "Security", "Changelog", "Press"];

    const posts = [
      { category: "General", date: "Apr 16", title: "A new programming model for durable execution", excerpt: "The gap between prototypes and production-ready systems is huge.", author: "Pranav Mehta" },
      { category: "General", date: "Apr 9", title: "Agentic Infrastructure", excerpt: "A new generation of infrastructure is emerging from coding agents.", author: "Tom Reeves" },
