      { category: "Customers", date: "Apr 1", title: "How a startup made a blog platform work for humans and AI alike", excerpt: "A two-person startup built an agentic CMS for businesses.", author: "Nic Vargas" },
      { category: "Engineering", date: "Mar 30", title: "Making build tool 96% faster with agents, sandboxes, and humans", excerpt: "Build tool is now significantly faster to compute task graphs at scale.", author: "Anthony Shew" },
      { category: "General", date: "Mar 25", title: "Unified reporting for all AI Gateway usage", excerpt: "AI usage data often spans providers and keys; reporting should not.", author: "Jerlyn and Dan" },
      { category: "General", date: "Mar 30", title: "Agent responsibly", excerpt: "A framework for shipping with agents while preserving engineering judgment.", author: "Matthew Carr" },
      { category: "Security", date: "Mar 20", title: "Hardening BotID for high-traffic production edges", excerpt: "How DeployCloud Security improved bot identity confidence across edge regions.", author: "Lina Hu" },
      { category: "Company News", date: "Mar 15", title: "DeployCloud announces expanded enterprise support", excerpt: "New dedicated support channels and architecture guidance for large organizations.", author: "Amar Sethi" },
      { category: "Community", date: "Mar 9", title: "Community showcase: projects built with DeployCloud Agent", excerpt: "A roundup of notable community-built tools powered by DeployCloud Agent.", author: "Samir Chen" },
      { category: "Press", date: "Mar 4", title: "DeployCloud featured in top developer platform rankings", excerpt: "Industry analysts highlight growth in developer adoption and performance.", author: "Editorial Team" },
      { category: "Changelog", date: "Feb 28", title: "Changelog: AI Gateway usage dashboards v2", excerpt: "Improved filtering, team-level breakdowns, and provider spend controls.", author: "Platform Team" },
      { category: "v0", date: "Feb 22", title: "Design-to-deploy with v0 and DeployCloud", excerpt: "From prompt to production: combining UI generation with cloud deployments.", author: "Product Team" }
    ];

    let activeCategory = "All Posts";
    let query = "";
    let visibleCount = 8;
    const pageSize = 3;

    const pillsEl = document.getElementById("categoryPills");
    const gridEl = document.getElementById("newsGrid");
    const searchInput = document.getElementById("searchInput");
    const noResultsEl = document.getElementById("noResults");
    const showMoreBtn = document.getElementById("showMoreBtn");

    function initials(author) {
      return author.split(/[ ,]+/).filter(Boolean).slice(0, 2).map(part => part[0]).join("").toUpperCase();
    }

    function normalizeCategory(cat) {
      return cat === "General" ? "All Posts" : cat;
    }

    function matches(post) {
      const categoryMatch = activeCategory === "All Posts" || post.category === activeCategory;
      const hay = (post.title + " " + post.excerpt + " " + post.author + " " + post.category).toLowerCase();
      const queryMatch = hay.includes(query.toLowerCase());
      return categoryMatch && queryMatch;
    }

    function renderPills() {
      pillsEl.innerHTML = "";
      categories.forEach(cat => {
        const b = document.createElement("button");
        b.className = "pill" + (cat === activeCategory ? " active" : "");
        b.textContent = cat;
        b.type = "button";
        b.setAttribute("aria-pressed", String(cat === activeCategory));
        b.addEventListener("click", () => {
          activeCategory = cat;
          visibleCount = 8;
          renderPills();
          renderPosts();
        });
        pillsEl.appendChild(b);
      });
    }

    function renderPosts() {
      const filtered = posts.filter(matches);
      const visible = filtered.slice(0, visibleCount);

      gridEl.innerHTML = "";
      visible.forEach(post => {
